import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "../components/Navbar";
import { useLocation } from "react-router-dom";

function Feedback() {

  const location = useLocation();

  const eventId = location?.state?.eventId || 1;
  const eventName = location?.state?.eventName || "College Event";

  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(false);

  /* =========================
     LOAD FEEDBACKS
  ========================= */

  useEffect(() => {

    const loadFeedbacks = async () => {

      try {

        setLoading(true);

        const res = await axios.get(`http://localhost:5000/feedback/${eventId}`);

        if (res && res.data) {

          if (Array.isArray(res.data)) {
            setFeedbacks(res.data);
          } else if (Array.isArray(res.data.data)) {
            setFeedbacks(res.data.data);
          } else {
            setFeedbacks([]);
          }

        } else {
          setFeedbacks([]);
        }

      } catch (error) {

        console.error("Fetch feedback error:", error);
        setFeedbacks([]);

      } finally {

        setLoading(false);

      }

    };

    loadFeedbacks();

  }, [eventId]);

  /* =========================
     SUBMIT FEEDBACK
  ========================= */

  const submitFeedback = async () => {

    if (comment.trim() === "") {
      alert("Please enter a comment");
      return;
    }

    try {

      await axios.post("http://localhost:5000/feedback", {
        user_id: 1,
        event_id: eventId,
        rating: rating,
        comment: comment
      });

      alert("Feedback submitted successfully");

      setComment("");
      setRating(5);

      // Reload feedback list
      const res = await axios.get(`http://localhost:5000/feedback/${eventId}`);

      if (Array.isArray(res.data)) {
        setFeedbacks(res.data);
      }

    } catch (error) {

      console.error("Submit feedback error:", error);
      alert("Failed to submit feedback");

    }

  };

  return (

    <div>

      <Navbar />

      <div
        style={{
          padding: "20px",
          maxWidth: "600px",
          margin: "auto"
        }}
      >

        <h2>Feedback for {eventName}</h2>

        {/* Rating */}

        <div style={{ marginBottom: "10px" }}>

          <label>Rating: </label>

          <select
            value={rating}
            onChange={(e) => setRating(Number(e.target.value))}
          >
            {[1,2,3,4,5].map((r) => (
              <option key={r} value={r}>
                {r} Star
              </option>
            ))}
          </select>

        </div>

        {/* Comment */}

        <div style={{ marginBottom: "10px" }}>

          <label>Comment:</label>

          <textarea
            style={{ width: "100%", height: "80px" }}
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />

        </div>

        <button onClick={submitFeedback}>
          Submit Feedback
        </button>

        <hr />

        <h3>All Feedback</h3>

        {loading && <p>Loading feedback...</p>}

        {!loading && feedbacks.length === 0 && (
          <p>No feedback available.</p>
        )}

        {!loading && feedbacks.map((f) => (

          <div
            key={f.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px"
            }}
          >

            <p>
              <b>{f.user_name || "User"}</b> rated {f.rating}/5
            </p>

            <p>{f.comment}</p>

            <p style={{ fontSize: "12px" }}>
              {f.created_at
                ? new Date(f.created_at).toLocaleString()
                : ""}
            </p>

          </div>

        ))}

      </div>

    </div>

  );

}

export default Feedback;
